import sys

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def add_years(self, years):
        self.age += years
        return self.age

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    name = lines[0].strip() if len(lines) > 0 else ""
    age = int(lines[1].strip()) if len(lines) > 1 else 0
    years = int(lines[2].strip()) if len(lines) > 2 else 0
    person = Person(name, age)
    print(person.add_years(years))

if __name__ == "__main__":
    main()
